<script setup lang="ts">
import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import {api,apiMessage,currentQueueOwner,serverScope} from '@/api/client';
import {requiresConnection} from '@/connectionState';
import {listOperations} from '@/offlineQueue';
import {readPrivateDraft,writePrivateDraft,deletePrivateDraft} from '@/privateDrafts';
import {localDate,shiftDate} from '@/todos';
import RestDaysPicker from '@/components/RestDaysPicker.vue';
import type {PageResponse,Plan,MainlineItem,Todo} from '@/types';
type RouteSummary={id:string;name:string;version:number;paused:boolean;archived:boolean;deletedAt:string|null;total:number;completed:number};
type Preview={checksum:string;tasks:number;stages:number;tags:number;milestones:number;changes:{id:string;title:string;beforeDate:string;afterDate:string;beforeMinutes:number;afterMinutes:number;beforeTag:string|null;afterTag:string|null}[];protectedItems:{id:string;title:string;reason:string}[];warnings:string[]};
type Pending={kind:'copy'|'batch';body:{request:Record<string,unknown>;checksum:string;operationKey:string;confirmed:true}};
const scope=serverScope(),owner=currentQueueOwner()??'';let active=true;onUnmounted(()=>{active=false;});const context=()=>active&&scope===serverScope()&&owner===currentQueueOwner();
const tab=ref('COPY'),error=ref(''),notice=ref(''),busy=ref(false),ready=ref(false),queue=ref(0),plans=ref<Plan[]>([]),routes=ref<PageResponse<RouteSummary>|null>(null),pending=ref<Pending|null>(null);
const routeSearch=ref(''),routeState=ref('ACTIVE'),routePage=ref(0),selectedRoute=ref<RouteSummary|null>(null),steps=ref<PageResponse<MainlineItem>|null>(null),stepSearch=ref(''),stepStatus=ref('ALL'),stepDeleted=ref(false),stepPage=ref(0);
const copy=reactive({kind:'PLAN',sourceId:'',name:'',startDate:localDate(),endDate:shiftDate(localDate(),30),restDays:[] as number[]});
const batch=reactive({planId:'',recurrenceId:'',from:shiftDate(localDate(),1),shiftDays:0,plannedMinutes:'' as number|'',replaceTag:false,tagId:''});
const batches=ref<{recurrenceId:string;title:string;taskCount:number}[]>([]),tags=ref<{id:string;name:string}[]>([]);
const preview=ref<Preview|null>(null),confirmed=ref(false),lastRequest=ref<Record<string,unknown>|null>(null),previewKind=ref<'copy'|'batch'>('copy');
const history=reactive({from:shiftDate(localDate(),-365),to:localDate(),search:'',status:'ALL',deleted:false,page:0});const todos=ref<PageResponse<Todo>|null>(null);
const locked=computed(()=>busy.value||!!pending.value),canApply=computed(()=>ready.value&&!requiresConnection()&&!queue.value&&!busy.value);
function invalidate(){preview.value=null;confirmed.value=false;lastRequest.value=null;}
watch([copy,batch],invalidate,{deep:true});watch(tab,()=>{if(!pending.value)invalidate();error.value='';});
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();}catch(e){if(context())error.value=apiMessage(e);}finally{if(context())busy.value=false;}}
async function loadRoutes(){const result=(await api.get<PageResponse<RouteSummary>>('/organize/routes',{params:{page:routePage.value,size:10,search:routeSearch.value,state:routeState.value}})).data;if(context())routes.value=result;}
async function searchRoutes(){routePage.value=0;selectedRoute.value=null;steps.value=null;await run(loadRoutes);}
async function moveRoutes(delta:number){routePage.value+=delta;await run(loadRoutes);}
async function selectRoute(row:RouteSummary){selectedRoute.value=row;stepPage.value=0;await run(loadSteps);}
async function loadSteps(){const line=selectedRoute.value;if(!line)return;const result=(await api.get<PageResponse<MainlineItem>>(`/mainlines/${line.id}/steps/page`,{params:{page:stepPage.value,size:10,search:stepSearch.value,status:stepStatus.value,deleted:stepDeleted.value}})).data;if(context()&&selectedRoute.value?.id===line.id)steps.value=result;}
async function searchSteps(){stepPage.value=0;await run(loadSteps);}
async function moveSteps(delta:number){stepPage.value+=delta;await run(loadSteps);}
async function togglePause(row:RouteSummary){await run(async()=>{await canStart();await api.put(`/mainlines/${row.id}/paused`,{version:row.version,paused:!row.paused});await loadRoutes();selectedRoute.value=routes.value?.content.find(line=>line.id===row.id)??null;await loadSteps();notice.value=row.paused?'路线已恢复，原阶段、依赖和历史保留。':'路线已暂停，原阶段、依赖和历史保留。';});}
function chooseSource(){const source=copy.kind==='PLAN'?plans.value.find(p=>p.id===copy.sourceId):routes.value?.content.find(p=>p.id===copy.sourceId);if(source){copy.name=source.name+'（副本）';if('startDate'in source){copy.startDate=source.startDate;copy.endDate=source.endDate;copy.restDays=[...(source.restDays??[])];}}}
async function loadBatch(){batches.value=[];tags.value=[];batch.recurrenceId='';if(!batch.planId)return;await run(async()=>{const [a,b]=await Promise.all([api.get(`/plans/${batch.planId}/recurrences`),api.get(`/plans/${batch.planId}/tags`)]);if(context()){batches.value=a.data;tags.value=b.data;}});}
async function makePreview(kind:'copy'|'batch'){
  await run(async()=>{await canStart();let request:Record<string,unknown>;
    if(kind==='copy')request={kind:copy.kind,sourceId:copy.sourceId,name:copy.name,startDate:copy.kind==='PLAN'?copy.startDate:null,endDate:copy.kind==='PLAN'?copy.endDate:null,restDaysMask:copy.restDays.reduce((n,d)=>n|(1<<(d-1)),0)};
    else request={...batch,plannedMinutes:batch.plannedMinutes===''?null:Number(batch.plannedMinutes),tagId:batch.tagId||null};
    const data=(await api.post<Preview>(`/organize/${kind}/preview`,request)).data;if(context()){preview.value=data;lastRequest.value=request;previewKind.value=kind;confirmed.value=false;}
  });
}
async function canStart(){if(!context())throw new Error('账号或服务器已变化，请重新打开本页。');if(requiresConnection())throw new Error('结构复制和批量编排需要联网，不会加入离线队列。');queue.value=(await listOperations(owner)).length;if(queue.value)throw new Error('当前账号有未同步操作，请先在同步中心处理，避免按旧云端内容编排。');}
async function apply(){await run(async()=>{await canStart();if(!pending.value){if(!preview.value||!lastRequest.value||!confirmed.value)return;const next:Pending={kind:previewKind.value,body:{request:lastRequest.value,checksum:preview.value.checksum,operationKey:crypto.randomUUID(),confirmed:true}};await writePrivateDraft(scope,owner,'organize-pending',next);if(!context())return;pending.value=next;}
    const next=pending.value;if(!next)return;const result=(await api.post<{id:string;changed:number;kind:string}>(`/organize/${next.kind}/apply`,next.body)).data;
    await deletePrivateDraft(scope,owner,'organize-pending');if(!context())return;pending.value=null;invalidate();notice.value=next.kind==='copy'?`结构副本已创建，包含 ${result.changed} 项任务／步骤。请在原模式中打开。`:`已调整 ${result.changed} 项未来实例，历史保持不变。`;plans.value=(await api.get<Plan[]>('/plans')).data;await loadRoutes();
  });}
async function resolveConflict(){if(!pending.value||!confirm('放弃此编号的再次提交并重新预览？如上次结果未知，请先原样重试确认，避免重复创建副本。'))return;await run(async()=>{await deletePrivateDraft(scope,owner,'organize-pending');pending.value=null;invalidate();notice.value='已保留表单；请重新预览。';});}
async function loadTodos(){const result=(await api.get<PageResponse<Todo>>('/todos/page',{params:{...history,size:10}})).data;if(context())todos.value=result;}
async function searchTodos(){history.page=0;await run(loadTodos);}
async function moveTodos(delta:number){history.page+=delta;await run(loadTodos);}
onMounted(()=>run(async()=>{pending.value=await readPrivateDraft<Pending>(scope,owner,'organize-pending')??null;if(pending.value&&!['copy','batch'].includes(pending.value.kind))throw new Error('本机编排记录无效，请保留数据并反馈。');queue.value=(await listOperations(owner)).length;plans.value=(await api.get<Plan[]>('/plans')).data;await loadRoutes();ready.value=true;}));
</script>
<template><div class="page organize-page">
  <header class="page-head"><div><h1>编排与历史</h1><p>复用结构、调整未来节奏，让长期目标按自己的时间推进。</p></div><router-link class="btn" to="/sync">查看同步队列</router-link></header>
  <p v-if="error" class="error-text" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
  <p v-if="queue" class="helper-text">当前设备有 {{queue}} 项本地操作。先处理同步，再进行复制或批量调整；不会自动清空队列。</p>
  <p v-if="requiresConnection()" class="helper-text">当前离线。本页编排需要联网；其他已缓存页面仍可按原规则使用。</p>
  <section v-if="pending" class="preview-panel" aria-label="待确认的编排结果"><h2>上次提交结果待确认</h2><p>请求已保存在当前账号和设备。原样重试会复用同一编号，不重复应用。</p><p>{{pending.body.request.name??'批量调整'}}</p><button class="btn primary" :disabled="busy||requiresConnection()" @click="apply">原样重试确认结果</button><button class="btn" :disabled="busy" @click="resolveConflict">已核对结果，重新预览</button></section>
  <nav class="button-row" aria-label="编排功能"><button v-for="(label,key) in {COPY:'结构复制',BATCH:'未来批量调整',ROUTES:'长路线查询',TODOS:'待办历史'}" :key="key" class="btn" :aria-pressed="tab===key" :disabled="locked" @click="tab=key">{{label}}</button></nav>
  <section v-if="tab==='COPY'" class="section"><h2>创建一套结构副本</h2><p>原记录保持不变；副本不带完成状态、计时流水或复盘。复制周期计划时，任务和里程碑按起点等距平移。</p>
    <form @submit.prevent="makePreview('copy')"><fieldset :disabled="locked"><div class="form-grid"><label>复制模式<select aria-label="复制模式" v-model="copy.kind" @change="copy.sourceId='' "><option value="PLAN">周期计划</option><option value="ROUTE">目标路线</option></select></label><label>来源<select aria-label="来源" v-model="copy.sourceId" required @change="chooseSource"><option value="">请选择</option><option v-for="item in copy.kind==='PLAN'?plans:routes?.content??[]" :key="item.id" :value="item.id">{{item.name}}</option></select></label></div>
      <p v-if="copy.kind==='ROUTE'" class="helper-text">可复制当前路线查询页的记录。其他路线请在“长路线查询”中搜索或翻页后再选择。</p><label>副本名称<input v-model="copy.name" required maxlength="120"/></label><template v-if="copy.kind==='PLAN'"><div class="form-grid"><label>副本开始日期<input v-model="copy.startDate" type="date" required/></label><label>副本结束日期<input v-model="copy.endDate" type="date" required/></label></div><RestDaysPicker v-model="copy.restDays"/></template></fieldset><button class="btn primary" :disabled="locked||!canApply||!copy.sourceId">预览结构复制</button></form>
  </section>
  <section v-if="tab==='BATCH'" class="section"><h2>只调整未来未开始实例</h2><p>已执行、已有验收记录或计时的实例保持不变。不会自动移动休息日，也不会修改更早历史。</p><form @submit.prevent="makePreview('batch')"><fieldset :disabled="locked"><div class="form-grid"><label>选择计划<select aria-label="选择计划" v-model="batch.planId" required @change="loadBatch"><option value="">请选择</option><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{plan.name}}</option></select></label><label>重复批次<select aria-label="重复批次" v-model="batch.recurrenceId" required><option value="">请选择</option><option v-for="item in batches" :key="item.recurrenceId" :value="item.recurrenceId">{{item.title}} · {{item.taskCount}} 项</option></select></label></div><div class="form-grid"><label>从此日期起<input v-model="batch.from" type="date" :min="shiftDate(localDate(),1)" required/></label><label>统一平移天数<input v-model.number="batch.shiftDays" type="number" min="-3660" max="3660" required/></label><label>计划分钟（留空保留）<input v-model="batch.plannedMinutes" type="number" min="1" max="1440"/></label></div><label class="check"><input v-model="batch.replaceTag" type="checkbox"/>同时替换标签</label><label v-if="batch.replaceTag">目标标签<select aria-label="目标标签" v-model="batch.tagId"><option value="">未分类</option><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{tag.name}}</option></select></label></fieldset><button class="btn primary" :disabled="locked||!canApply||!batch.recurrenceId">预览批量差异</button></form></section>
  <section v-if="preview" class="section preview-panel" aria-label="编排差异预览"><h2>确认前预览</h2><p>{{preview.tasks}} 项任务／步骤 · {{preview.stages}} 个阶段 · {{preview.tags}} 个标签 · {{preview.milestones}} 个里程碑</p><p v-for="warning in preview.warnings" :key="warning">{{warning}}</p><article v-for="item in preview.changes" :key="item.id" class="difference"><h3>{{item.title}}</h3><div><span>变更前</span><p>{{item.beforeDate}} · {{item.beforeMinutes}} 分钟 · {{tags.find(t=>t.id===item.beforeTag)?.name??'未分类'}}</p></div><div><span>变更后</span><p>{{item.afterDate}} · {{item.afterMinutes}} 分钟 · {{tags.find(t=>t.id===item.afterTag)?.name??'未分类'}}</p></div></article><h3 v-if="preview.protectedItems.length">以下记录保持不变</h3><p v-for="item in preview.protectedItems" :key="item.id">{{item.title}}：{{item.reason}}</p><label class="check"><input v-model="confirmed" type="checkbox" :disabled="locked"/>我已核对预览，确认应用以上变更。</label><button class="btn primary" :disabled="!confirmed||locked||!canApply" @click="apply">{{previewKind==='copy'?'确认创建副本':'确认应用批量调整'}}</button></section>
  <section v-if="tab==='ROUTES'" class="section"><h2>长路线查询</h2><p>按服务器分页读取，不一次下载全部路线内容。依赖解锁仍依据服务端完整关系判断。</p><form class="form-grid" @submit.prevent="searchRoutes"><label>搜索路线<input v-model="routeSearch" maxlength="120"/></label><label>路线状态<select aria-label="路线状态" v-model="routeState"><option value="ACTIVE">未归档（含暂停）</option><option value="PAUSED">暂停中</option><option value="ARCHIVED">已归档</option><option value="TRASH">回收站</option></select></label><button class="btn" :disabled="busy">查询路线</button></form><article v-for="line in routes?.content??[]" :key="line.id" class="record-row"><div><h3>{{line.name}}</h3><p>{{line.completed}} / {{line.total}} 已完成 · {{line.paused?'路线暂停中':'路线未暂停'}}</p></div><div class="button-row"><button class="btn" :disabled="busy||!!line.deletedAt" @click="selectRoute(line)">查看步骤</button><button v-if="!line.archived&&!line.deletedAt" class="btn" :disabled="locked||requiresConnection()||!!queue" @click="togglePause(line)">{{line.paused?'恢复路线':'暂停路线'}}</button><router-link v-if="!line.archived&&!line.deletedAt" class="btn" :to="{path:'/mainlines',query:{line:line.id}}">编辑结构</router-link></div></article><p v-if="routes&&!routes.totalElements">没有匹配的路线。</p><div v-if="routes" class="pagination-bar"><span>第 {{routePage+1}} 页 · 共 {{routes.totalElements}} 条路线</span><button class="btn" :disabled="busy||routePage===0" @click="moveRoutes(-1)">上一页路线</button><button class="btn" :disabled="busy||routePage+1>=routes.totalPages" @click="moveRoutes(1)">下一页路线</button></div>
    <section v-if="selectedRoute" class="steps-panel" aria-label="分页步骤"><h3>{{selectedRoute.name}} · 步骤</h3><form class="form-grid" @submit.prevent="searchSteps"><label>搜索步骤<input v-model="stepSearch" maxlength="180"/></label><label>步骤状态<select aria-label="步骤状态" v-model="stepStatus"><option value="ALL">全部</option><option value="OPEN">未完成</option><option value="COMPLETED">已完成</option></select></label><label class="check"><input v-model="stepDeleted" type="checkbox"/>只看已删除步骤</label><button class="btn" :disabled="busy">查询步骤</button></form><article v-for="item in steps?.content??[]" :key="item.id" class="record-row"><div><h4>{{item.title}}</h4><p>{{item.description}}</p><small>{{item.status}} · {{item.accumulatedSeconds}} 秒 · {{item.unlocked?'前置条件已满足':'暂不可开始'}}</small></div></article><div v-if="steps" class="pagination-bar"><span>第 {{stepPage+1}} 页 · 共 {{steps.totalElements}} 个步骤</span><button class="btn" :disabled="busy||stepPage===0" @click="moveSteps(-1)">上一页步骤</button><button class="btn" :disabled="busy||stepPage+1>=steps.totalPages" @click="moveSteps(1)">下一页步骤</button></div></section>
  </section>
  <section v-if="tab==='TODOS'" class="section"><h2>待办历史</h2><p>查询更长日期范围的待办和回收站，每次从服务器读取 10 项。</p><form class="form-grid" @submit.prevent="searchTodos"><label>历史开始日期<input v-model="history.from" type="date" required/></label><label>历史结束日期<input v-model="history.to" type="date" required/></label><label>历史关键词<input v-model="history.search" maxlength="180"/></label><label>历史状态<select aria-label="历史状态" v-model="history.status"><option value="ALL">全部</option><option value="OPEN">未完成</option><option value="DONE">已完成</option></select></label><label class="check"><input v-model="history.deleted" type="checkbox"/>只看待办回收站</label><button class="btn" :disabled="busy||requiresConnection()">查询待办历史</button></form><article v-for="item in todos?.content??[]" :key="item.id" class="record-row"><div><h3>{{item.title}}</h3><p>{{item.note}}</p><small>{{item.dueDate}} · {{item.done?'已完成':'未完成'}}</small></div><router-link class="btn" :to="{path:'/todos',query:{date:item.dueDate,focus:item.id}}">返回当天待办</router-link></article><p v-if="todos&&!todos.totalElements">没有匹配的待办。</p><div v-if="todos" class="pagination-bar"><span>第 {{history.page+1}} 页 · 共 {{todos.totalElements}} 项</span><button class="btn" :disabled="busy||history.page===0" @click="moveTodos(-1)">上一页待办</button><button class="btn" :disabled="busy||history.page+1>=todos.totalPages" @click="moveTodos(1)">下一页待办</button></div></section>
</div></template>
<style scoped>
.organize-page>.button-row{margin-bottom:24px}.organize-page [aria-pressed=true]{background:#002fa7;color:#fff}.organize-page .section{padding:24px;margin-bottom:24px}.organize-page form,.organize-page fieldset{display:grid;gap:18px}.organize-page fieldset{border:0;padding:0;min-width:0}.organize-page label{display:grid;gap:8px}.organize-page .check{display:flex;align-items:center;gap:10px}.organize-page input[type=checkbox]{width:20px;height:20px;min-height:20px;flex:0 0 20px;accent-color:#002fa7}.preview-panel{border:1px solid #002fa7;padding:24px;background:#f7f7f8;margin-bottom:24px}.difference{border-top:1px solid #d8d8df;padding:20px 0;display:grid;grid-template-columns:1fr 1fr;gap:12px}.difference h3{grid-column:1/-1}.difference span{color:#002fa7;font-weight:700}.record-row{padding:20px 0;border-bottom:1px solid #d8d8df;display:flex;gap:18px;justify-content:space-between;align-items:center}.record-row>div{min-width:0}.record-row p{white-space:pre-wrap;overflow-wrap:anywhere}.steps-panel{margin-top:32px;border-top:1px solid #d8d8df;padding-top:24px}.organize-page h3,.organize-page h4{overflow-wrap:anywhere}.organize-page .pagination-bar{flex-wrap:wrap;gap:12px}
@media(max-width:700px){.organize-page .section,.preview-panel{padding:16px}.record-row{display:grid}.difference{grid-template-columns:minmax(0,1fr)}.organize-page>.button-row .btn{flex:1 1 40%}.organize-page .form-grid{grid-template-columns:minmax(0,1fr)}.organize-page .btn{white-space:normal}.organize-page input,.organize-page select{min-width:0;max-width:100%}}
</style>
